// app/components/SyncUser.tsx
"use client";
import { useUser, useAuth, SignUp } from "@clerk/nextjs";
import { useEffect } from "react";

export default function SyncUser() {
  const { user, isLoaded } = useUser();
  const { getToken } = useAuth();

  useEffect(() => {
    const sync = async () => {
      if (isLoaded && user) {
        const token = await getToken(); // Get the JWT for the backend

        await fetch(`${process.env.NEXT_PUBLIC_API_URL}/users/sync`, {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        });
      }
    };
    sync();
  }, [isLoaded, user, getToken]);

 
    return (
    <div className="flex min-h-screen items-center justify-center bg-background">
      <SignUp 
        path="/sign-up" 
        routing="path" 
        signInUrl="/sign-in"
        // After signing up, Clerk sends them to the dashboard
        // where your <SyncUser /> component will trigger immediately.
        forceRedirectUrl="/dashboard" 
      />
    </div>
  );
  
}
